bool Enabled(uint32_t va) {
  static const std::set<uint32_t> off = [] {
    std::set<uint32_t> s;
    const char* e = std::getenv("GTAIV_NATIVE_OFF");
    while (e && *e) {
      char* end;
      s.insert(uint32_t(std::strtoul(e, &end, 16)));
      e = *end ? end + 1 : end;
    }
    return s;
  }();
  return !off.count(va);
}

